spec.process-compute.config:
// Compute configuration for epi2me-labs/wf-demo v1.2.3.
// Executor, queue and instance sizing come from the Cirro compute environment chosen
// at launch; the workflow's own config declares per-process cpu and memory requests.

process {
    errorStrategy = { task.exitStatus in [143, 137, 104, 134, 139] ? 'retry' : 'finish' }
    maxRetries = 2
}

spec.process-form.json:
{
  "ui": {},
  "form": {
    "type": "object",
    "properties": {
      "input": {
        "type": "object",
        "title": "Input",
        "properties": {
          "ref": {
            "type": "string",
            "title": "Ref",
            "pathType": "references",
            "file": "**/*.{fa,fasta,fna}{,.gz}",
            "description": "Path to a reference FASTA file"
          },
          "bed": {
            "type": "string",
            "title": "Bed",
            "pathType": "dataset",
            "file": "**/*.bed",
            "description": "Optional BED of regions"
          },
          "sample_name": {
            "type": "string",
            "title": "Sample name",
            "description": "Sample name"
          }
        },
        "required": [
          "ref"
        ]
      },
      "workflow": {
        "type": "object",
        "title": "Workflow",
        "properties": {
          "snp": {
            "type": "boolean",
            "title": "Snp",
            "description": "Call small variants",
            "default": false
          }
        }
      },
      "advanced": {
        "type": "object",
        "title": "Advanced",
        "properties": {
          "depth": {
            "type": "integer",
            "title": "Depth",
            "description": "Minimum depth"
          },
          "aligner": {
            "type": "string",
            "enum": [
              "minimap2",
              "bwa"
            ],
            "title": "Aligner",
            "description": "Aligner",
            "default": "minimap2"
          }
        },
        "required": [
          "depth"
        ]
      }
    }
  }
}

